class CorpusProvider:
    spec = ProviderSpec("fixture_search", "1", "合成内容", "fixture", "fixture_only")

    def __init__(self):
        self.late = None
        self.calls = 0

    async def step(self, job, _budget):
        self.calls += 1
        ordinal = job.completed_units
        name = job.original_ref.object_ref
        timed = name == "generated-001"
        last = name != self.late or ordinal == 9
        text = ("PRIVATE_SENTINEL" if name == "private-document" else "保险计划" if name == self.late and ordinal == 9
                else '公共课程 café 100%_proof "quoted" 星')
        anchor = StewardSourceAnchor(content_id=job.content_id, original_ref=job.original_ref,
                                     kind="audio_time" if timed else "page",
                                     **({"start_ms": 60000, "end_ms": 61000} if timed else {"page": ordinal + 1}))
        unit = StewardUnit(unit_id=digest([job.job_id, ordinal]), ordinal=ordinal, title="资料 " + name,
                           text=text, anchor=anchor, provider=job.provider, provider_version=job.provider_version)
        return ExtractionStep([unit], None if last else "generated-cursor-" + str(ordinal + 1), last)


@pytest.fixture
async def corpus(tmp_path):
    reader = SyntheticNASReader()
    public = {"generated-" + str(i).zfill(3) for i in range(60)} | {"not-extracted"}
    for name in public:
        reader.put(name, ("GENERATED bytes " + name).encode(), kind="other")
    reader.put("private-document", b"GENERATED private separate bytes", kind="other")
    reader.put("private-alias", reader.objects["generated-000"]["bytes"], kind="other")
    clock = [datetime(2026, 10, 9, tzinfo=UTC)]
    connection = sqlite3.connect(tmp_path / "generated.sqlite")
    catalog = FamilyMediaCatalog(connection, reader, simulated=True, clock=lambda: clock[0],
                                 indexed_kinds=("image", "audio", "video", "other"))
    for directory, names, rounds in [("public", public, 18), ("private", {"private-document", "private-alias"}, 3)]:
        reader.listing = names
        for _ in range(rounds):
            await catalog.scan(FamilyMediaScanRequest(expected_context=(await catalog.context()).fingerprint,
                                                      directory_ref=directory, restart_scan=True))
            clock[0] += timedelta(seconds=3)
    ctx = await catalog.context()
    all_items = (await catalog.list_items(FamilyMediaQuery(expected_context=ctx.fingerprint, limit=100))).items
    assert len(all_items) == 63 and all(item.status == "ready" for item in all_items)
    late = next(item for item in reversed(all_items[50:]) if item.original_ref.object_ref in public - {"not-extracted", "generated-001"})
    provider = CorpusProvider(); provider.late = late.original_ref.object_ref
    steward = FileSteward(connection, catalog, clock=lambda: clock[0], fixture_provider=provider)
    for item in all_items:
        if item.original_ref.object_ref in {"not-extracted", "private-alias"}:
            continue
        job = (await steward.plan_jobs(StewardJobRequest(expected_context=ctx.fingerprint,
                         item_ids=[item.item_id], provider=provider.spec.key)))[0]
        for _ in range(10 if item.item_id == late.item_id else 1):
            await steward.run_fixture_step(job.job_id, ctx.fingerprint)
    reader.calls.clear(); baseline = provider.calls
    yield steward, catalog, reader, clock, connection, late, provider
    assert not reader.calls and provider.calls == baseline, "Search must not scan/stat/read bytes or invoke extraction"
    await catalog.close(); connection.close()


async def request(corpus, query="", **kwargs):
    return StewardPageRequest(expected_context=(await corpus[1].context()).fingerprint,
                              query=query, search_mode="indexed_cache", **kwargs)


async def test_actual_late_catalog_page_and_late_citation(corpus):
    steward, catalog, _, _, _, late, _ = corpus
    legacy = await steward.page(StewardPageRequest(expected_context=(await catalog.context()).fingerprint, query="保险计划"))
    assert legacy["items"] == [] and legacy["next_cursor"] and legacy["search_scope"] == "catalog_page"
    result = await steward.page(await request(corpus, "保险计划"))
    assert [row["item"].item_id for row in result["items"]] == [late.item_id]
    ref = result["items"][0]["references"][0]
    assert ref.anchor.original_ref == late.original_ref and ref.anchor.page == 10 and ref.text == "保险计划"
    assert result["items"][0]["matched_reference_count"] == 1
    assert result["search_scope"] == "indexed_cache" and not result["coverage"]["source_read_enabled"]
    assert not result["coverage"]["complete_source_scan_claimed"]


@pytest.mark.parametrize("query", ["公共课程", "星", "fé", "CAFE\u0301", "100%_proof", '"quoted"', " OR "])
async def test_literal_unicode_short_wildcard_and_fts_syntax(corpus, query):
    result = await corpus[0].page(await request(corpus, query, limit=100))
    assert len(result["items"]) == (0 if query == " OR " else 60)
    assert all(any(query.casefold().replace("cafe\u0301", "café") in (u.title + " " + u.text).casefold()
                   for u in row["references"]) for row in result["items"])


async def test_pagination_unique_replay_and_matched_time_reference(corpus):
    req = await request(corpus, "公共课程", limit=7)
    seen, pages, cursor = [], [], None
    while True:
        result = await corpus[0].page(req.model_copy(update={"cursor": cursor}))
        ids = [row["item"].item_id for row in result["items"]]
        assert ids == sorted(ids) and not set(ids) & set(seen)
        seen.extend(ids); pages.append(result)
        for row in result["items"]:
            if row["item"].original_ref.object_ref == "generated-001":
                assert row["references"][0].anchor.kind == "audio_time"
                assert row["references"][0].anchor.start_ms == 60000
        cursor = result["next_cursor"]
        if not cursor:
            break
    assert len(seen) == 60 and len(pages) == 9
    replay = await corpus[0].page(req.model_copy(update={"cursor": pages[0]["next_cursor"]}))
    assert [r["item"].item_id for r in replay["items"]] == [r["item"].item_id for r in pages[1]["items"]]


async def test_scoped_private_alias_and_unindexed_originals(corpus):
    result = await corpus[0].page(await request(corpus, "PRIVATE_SENTINEL"), directory_refs=["public"])
    assert not result["items"]
    result = await corpus[0].page(await request(corpus, "PRIVATE_SENTINEL"), directory_refs=["private"])
    assert len(result["items"]) == 1
    all_indexed = await corpus[0].page(await request(corpus, limit=100))
    assert len(all_indexed["items"]) == 61
    names = {row["item"].original_ref.object_ref for row in all_indexed["items"]}
    assert "private-alias" not in names and "not-extracted" not in names
    scoped = await corpus[0].page(await request(corpus, "公共课程", limit=100), directory_refs=["private"])
    assert scoped["items"] == []


async def test_cursor_query_limit_directory_foreign_expiry_and_policy(corpus):
    steward = corpus[0]; req = await request(corpus, "公共课程", limit=2)
    result = await steward.page(req, directory_refs=["public"]); token = result["next_cursor"]
    for changed, dirs in [({"query": "星"}, ["public"]), ({"limit": 3}, ["public"]), ({}, ["private"]),
                          ({"cursor": "f" * 64}, ["public"]), ({}, None)]:
        with pytest.raises(StewardError, match="search_cursor_changed"):
            await steward.page(req.model_copy(update={"cursor": token, **changed}), directory_refs=dirs)
    ctx = await corpus[1].context()
    await steward.set_policy(StewardPolicyEdit(expected_context=ctx.fingerprint,
        rule=StewardPolicyRule(rule_id="generated-policy", source_ref=ctx.source_ref,
        config_generation=ctx.config_generation, connection_epoch=ctx.connection_epoch,
        directory_ref="public", label="生成保留")))
    with pytest.raises(StewardError, match="search_cursor_changed"):
        await steward.page(req.model_copy(update={"cursor": token}), directory_refs=["public"])
    result = await steward.page(req); steward.search.monotonic = lambda: 10**20
    with pytest.raises(StewardError, match="search_cursor_changed"):
        await steward.page(req.model_copy(update={"cursor": result["next_cursor"]}))


async def test_unit_revision_rebuild_and_replacement_invalidates_cursor(corpus):
    steward, _, _, _, conn, late, _ = corpus
    req = await request(corpus, limit=2); token = (await steward.page(req))["next_cursor"]
    row = conn.execute("SELECT id,body FROM steward_units ORDER BY id LIMIT 1").fetchone()
    unit = StewardUnit.model_validate_json(row[1]).model_copy(update={"text": "新生成搜索标记"})
    with conn:
        conn.execute("UPDATE steward_units SET body=? WHERE id=?", (unit.model_dump_json(), row[0]))
    with pytest.raises(StewardError, match="search_cursor_changed"):
        await steward.page(req.model_copy(update={"cursor": token}))
    assert len((await steward.page(await request(corpus, "新生成搜索标记")))["items"]) == 1
    # Owner metadata revision now disagrees with the committed extraction anchor.
    with conn:
        saved = json.loads(conn.execute("SELECT body FROM family_media_items WHERE item_id=?", (late.item_id,)).fetchone()[0])
        saved["revision"] = "generated-replacement"
        conn.execute("UPDATE family_media_items SET body=? WHERE item_id=?", (json.dumps(saved), late.item_id))
        corpus[1]._bump()
    assert not (await steward.page(await request(corpus, "保险计划")))["items"]


async def test_offline_stale_and_source_epoch_are_not_current_hits(corpus):
    steward, catalog, reader, clock, _, _, _ = corpus
    req = await request(corpus, "公共课程", limit=2); token = (await steward.page(req))["next_cursor"]
    reader.state = "stopped"  # Existing ReaderStatus protocol; not an invented offline enum.
    result = await steward.page(await request(corpus, "公共课程"))
    assert not result["items"] and result["coverage"]["source_online"] is False
    reader.state = "online"; clock[0] += timedelta(seconds=61)
    assert not (await steward.page(await request(corpus, "公共课程")))["items"]
    reader.epoch = "generated-new-epoch"
    with pytest.raises(StewardError, match="steward_context_changed"):
        await steward.page(req.model_copy(update={"cursor": token}))
    result = await steward.page(await request(corpus, "公共课程"))
    assert not result["items"]


async def test_actual_asgi_query_and_legacy_cursor_separation(corpus):
    app = FastAPI(); app.include_router(create_router(corpus[0]))  # Router already owns /api/files.
    async with httpx.AsyncClient(transport=httpx.ASGITransport(app=app), base_url="http://generated") as client:
        req = await request(corpus, "保险计划")
        result = await client.post("/api/files/query", json=req.model_dump(mode="json"))
        assert result.status_code == 200 and result.json()["items"][0]["references"][0]["anchor"]["page"] == 10
        indexed = await client.post("/api/files/query", json=(await request(corpus, limit=2)).model_dump(mode="json"))
        token = indexed.json()["next_cursor"]
        legacy = StewardPageRequest(expected_context=req.expected_context, cursor=token)
        rejected = await client.post("/api/files/query", json=legacy.model_dump(mode="json"))
        assert rejected.status_code == 409
        nul = await client.post("/api/files/query", json=req.model_copy(update={"query": "\x00"}).model_dump(mode="json"))
        assert nul.status_code == 409 and nul.json()["detail"]["code"] == "steward_invalid_search_query"


async def test_actual_agent_grant_identity_scope_and_late_revocation(corpus):
    ctx = await corpus[1].context(); clock = corpus[3]
    scope = StewardAgentReadScope(grant_id="generated-grant", subject_ref="generated-subject", source_ref=ctx.source_ref,
        config_generation=ctx.config_generation, connection_epoch=ctx.connection_epoch, directory_refs=["public"],
        approved_at=clock[0], expires_at=clock[0]+timedelta(minutes=5))
    agent = AgentLoopFiles(corpus[0], scope_authorizer=lambda _: True, clock=lambda: clock[0])
    req = await request(corpus, "公共课程", limit=2)
    first = await agent.query(scope, req)
    assert first["source_read_enabled"] is False and all("jobs" not in r for r in first["items"])
    changed = scope.model_copy(update={"grant_id": "generated-other-grant"})
    with pytest.raises(StewardError, match="search_cursor_changed"):
        await agent.query(changed, req.model_copy(update={"cursor": first["next_cursor"]}))
    assert not (await agent.query(scope, await request(corpus, "PRIVATE_SENTINEL")))["items"]
    calls = [0]
    def revoke(_):
        calls[0] += 1
        return calls[0] == 1
    before = set(corpus[0].search.cursors)
    agent.authorizer = revoke
    with pytest.raises(StewardError, match="scope_denied"):
        await agent.query(scope, req)
    assert set(corpus[0].search.cursors) == before


async def test_cancel_and_late_policy_change_discard_results(corpus):
    steward = corpus[0]; req = await request(corpus, "公共课程", limit=2)
    await steward.page(req); before = set(steward.search.cursors)
    original = steward._project_page; entered = asyncio.Event(); release = asyncio.Event()
    async def blocked(*args, **kwargs):
        entered.set(); await release.wait(); return await original(*args, **kwargs)
    steward._project_page = blocked
    task = asyncio.create_task(steward.page(req)); await entered.wait(); task.cancel()
    with pytest.raises(asyncio.CancelledError):
        await task
    assert set(steward.search.cursors) == before

    entered.clear(); task = asyncio.create_task(steward.page(req)); await entered.wait()
    with corpus[4]:
        corpus[4].execute("UPDATE steward_policy_epoch SET revision=revision+1 WHERE id=1")
    release.set()
    with pytest.raises(StewardError, match="search_changed"):
        await task
    assert set(steward.search.cursors) == before


async def test_capture_actual_asgi_payload_for_real_console_consumer(corpus, tmp_path):
    app = FastAPI(); app.include_router(create_router(corpus[0]))
    async with httpx.AsyncClient(transport=httpx.ASGITransport(app=app), base_url="http://generated") as client:
        async def query(req):
            result = await client.post("/api/files/query", json=req.model_dump(mode="json"))
            assert result.status_code == 200
            return result.json()
        ctx = (await client.get("/api/files/context")).json()
        needle = await query(await request(corpus, "保险计划"))
        req = await request(corpus, "公共课程")
        public = await query(req)
        more = await query(req.model_copy(update={"cursor": public["next_cursor"]}))
        files = await query(StewardPageRequest(expected_context=req.expected_context))
        assert len(public["items"]) == 50 and len(more["items"]) == 10
        assert not {r["item"]["item_id"] for r in public["items"]} & {r["item"]["item_id"] for r in more["items"]}
        assert needle["items"][0]["references"][0]["anchor"]["page"] == 10
        payload = {"basis": "actual_same_origin_ASGI_generated_cache", "context": ctx, "needle": needle,
                   "public": public, "more": more, "files": files, "late_item_id": corpus[5].item_id,
                   "source_IO_calls": list(corpus[2].calls), "provider_calls_during_queries": 0}
        target = Path(os.environ.get("FRIDAY_SEARCH_CAPTURE_PATH", str(tmp_path / "capture.json")))
        target.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n")


async def test_provider_change_and_new_consumer_do_not_reuse_old_cursor(corpus):
    steward = corpus[0]; req = await request(corpus, "公共课程", limit=2)
    first = await steward.page(req)
    key = corpus[6].spec.key
    spec = steward.providers[key]
    steward.providers[key] = ProviderSpec(spec.key, "unqualified", spec.label, spec.environment, spec.qualification)
    with pytest.raises(StewardError, match="search_cursor_changed"):
        await steward.page(req.model_copy(update={"cursor": first["next_cursor"]}))
    assert not (await steward.page(req))["items"]
    steward.providers[key] = spec
    first = await steward.page(req)
    replacement = FileSteward(corpus[4], corpus[1], clock=lambda: corpus[3][0], fixture_provider=corpus[6])
    with pytest.raises(StewardError, match="search_cursor_changed"):
        await replacement.page(req.model_copy(update={"cursor": first["next_cursor"]}))
    assert len((await replacement.page(req))["items"]) == 2


async def test_late_source_configuration_and_unit_change_discard_results(corpus):
    steward = corpus[0]; req = await request(corpus, "公共课程", limit=2)
    await steward.page(req); before = set(steward.search.cursors)
    original = steward._project_page; entered = asyncio.Event(); release = asyncio.Event()
    async def blocked(*args, **kwargs):
        entered.set(); await release.wait(); return await original(*args, **kwargs)
    steward._project_page = blocked
    task = asyncio.create_task(steward.page(req)); await entered.wait()
    corpus[2].generation += 1; release.set()
    with pytest.raises(StewardError, match="steward_context_changed"):
        await task
    assert set(steward.search.cursors) == before

    corpus[2].generation -= 1; entered.clear(); release.clear()
    task = asyncio.create_task(steward.page(req)); await entered.wait()
    with corpus[4]:
        saved = corpus[4].execute("SELECT id,body FROM steward_units LIMIT 1").fetchone()
        unit = StewardUnit.model_validate_json(saved[1]).model_copy(update={"text": "生成修改后内容"})
        corpus[4].execute("UPDATE steward_units SET body=? WHERE id=?", (unit.model_dump_json(), saved[0]))
    release.set()
    with pytest.raises(StewardError, match="search_changed"):
        await task
    assert set(steward.search.cursors) == before


async def test_unqualified_cached_job_cannot_supply_indexed_title_or_status(corpus):
    steward, _, _, _, conn, late, _ = corpus
    good = next(job for job in steward.jobs() if job.item_id == late.item_id)
    bad = good.model_copy(update={"job_id": digest([good.job_id, "generated-unqualified"]),
                                 "provider": "docling", "provider_version": "unqualified"})
    last = steward.units(good.job_id)[-1]
    unit = last.model_copy(update={"unit_id": digest([last.unit_id, "generated-unqualified"]),
                                  "title": "UNQUALIFIED_TITLE", "text": "保险计划 UNQUALIFIED_TEXT",
                                  "provider": "docling", "provider_version": "unqualified"})
    # Generated legacy cache control, not provider invocation or real content.
    with conn:
        steward._save_job(bad)
        conn.execute("INSERT INTO steward_units VALUES (?,?,?)", (unit.unit_id, bad.job_id, unit.model_dump_json()))
    result = await steward.page(await request(corpus, "保险计划"))
    row = result["items"][0]
    assert row["title"] == last.title
    assert all(job.provider == good.provider for job in row["jobs"])
    assert all(state["provider"] == good.provider for state in row["provider_states"])
    assert all(ref.provider == good.provider for ref in row["references"])
